pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount == 10 ether);

        // Record the timestamp before the call
        uint256 timestampBefore = block.timestamp;

        // Make the call
        (bool success, ) = address(c).call{value: amount}("");

        if (success) {
            // The rule: pastBlockTime should equal the block.timestamp at the time of the call
            // (which is at least timestampBefore, and is exactly the timestamp when pastBlockTime was set)
            uint256 pastBlockTimeAfter = c.pastBlockTime();
            assertTrue(pastBlockTimeAfter == timestampBefore || pastBlockTimeAfter == timestampBefore + 1 || pastBlockTimeAfter == timestampBefore - 1);
        } else {
            // If it reverted, pastBlockTime should remain unchanged (so the rule holds vacuously)
            assertTrue(true);
        }
    }
}

