pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber) public {
        // Ensure the block number modulo works as expected
        vm.assume(blockNumber % 15 == 0);
        vm.deal(address(c), 10 ether);
        vm.txGasPrice(0);
        // Warp to a timestamp that is always greater than pastBlockTime (which is 0 initially)
        vm.warp(1);
        // Roll to the target block number
        vm.roll(blockNumber);
        // Call fallback with exactly 1 ether (mutant version) or 10 ether (original)
        // We test the mutant condition by sending 1 ether
        (bool success, ) = address(c).call{value: 1 ether}("");
        assertTrue(success);
        // After the call, since blockNumber % 15 == 0, the contract should have transferred all balance
        assertTrue(address(c).balance == 0 ether);
    }
}

