pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 blockNumber, uint256 timestamp) public {
        // Constrain the amount to exactly 10 ether (reference works) or 1 ether (buggy)
        amount = bound(amount, 1 ether, 2 ether);

        // Ensure timestamp is strictly greater than pastBlockTime (initially 0)
        vm.assume(timestamp > c.pastBlockTime());

        // Set block context
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // Fund the test contract to send ether
        vm.deal(address(this), amount);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Attempt to call fallback
        (bool success, ) = address(c).call{value: amount}("");

        // Read balance after
        uint256 balanceAfter = address(c).balance;

        // The general rule: The balance decreases (due to transfer) IF AND ONLY IF 
        // the call succeeded, exactly 10 ether was sent, and block.number % 15 == 0
        bool callSucceeded = success;
        bool correctAmount = (amount == 10 ether);
        bool divisibleBy15 = (blockNumber % 15 == 0);

        // For the reference: balance decreases iff call succeeds, amount is 10 ether, and block%15==0
        // However, the call might fail due to wrong amount or timestamp condition.
        // The balance only decreases (via transfer) when all conditions are met.
        assertTrue(
            (balanceAfter < balanceBefore) == 
            (callSucceeded && correctAmount && divisibleBy15)
        );
    }
}

