pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeJump) public {
        // Bound the fuzz inputs to reasonable values
        amount = bound(amount, 10 ether, 1000 ether);
        timeJump = bound(timeJump, 1, 1000);

        // Provide enough ether to the contract for the fallback to work
        vm.deal(address(c), 100 ether);

        // Call fallback with exactly 10 ether via sending ether
        vm.prank(address(0xdead));
        (bool success, ) = address(c).call{value: amount}('');

        // Simulate time passing
        vm.warp(block.timestamp + timeJump);

        // Now call fallback again with 10 ether to trigger the require and possibly the if
        vm.prank(address(0xdead));
        (success, ) = address(c).call{value: 10 ether}('');

        // The rule: if the call succeeded and block.number % 15 != 0, then pastBlockTime must be > 0
        // In the reference, pastBlockTime is set to block.timestamp and never reset to 0.
        // In the mutant, if block.number % 15 == 0, pastBlockTime is set to 0 after transfer.
        // So we check that pastBlockTime is NEVER zero after any call that does not involve the if block resetting it.
        // Simple check: after any successful fallback call, pastBlockTime should be non-zero.
        assertTrue(c.pastBlockTime() > 0);
    }
}

