pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, uint256 timeJump) public {
        vm.assume(value == 10 ether);
        vm.assume(timeJump > 0 && timeJump <= 1000000);

        uint256 prev = c.pastBlockTime();
        vm.warp(block.timestamp + timeJump);

        // Call fallback via sending ETH
        (bool success, ) = address(c).call{value: value}("");
        if (success) {
            assertTrue(c.pastBlockTime() > prev);
        } else {
            assertTrue(c.pastBlockTime() == prev);
        }
    }
}

