contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, uint256 blockTimeOffset) public {
        // Bound parameters to reasonable range
        value = bound(value, 10 ether, 10 ether); // Must be exactly 10 ether
        blockTimeOffset = bound(blockTimeOffset, 1, 1000);

        // First call succeeds
        vm.deal(address(this), 10 ether);

        // Set block timestamp to something > pastBlockTime (initially 0)
        vm.warp(block.timestamp + blockTimeOffset);

        // Force a block number that is NOT a multiple of 15 so the if() doesn't trigger
        uint256 blockNum = block.number;
        if (blockNum % 15 == 0) {
            vm.roll(blockNum + 1);
        }

        // Call fallback - should succeed
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1, "First call should succeed");

        // Now call again within the SAME block (no time advance)
        // In the reference, this should revert because pastBlockTime == current timestamp
        // In the mutant, pastBlockTime was reset to 0 after the transfer (if block %15 ==0)
        // But since we ensured block %15 != 0, the transfer didn't happen, so no difference?
        // So we need to also test the case where block %15 == 0
    }
}

