pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timeJump) public {
        timeJump = bound(timeJump, 1, 100);
        vm.warp(block.timestamp + timeJump);

        // First call: should succeed and set pastBlockTime = block.timestamp
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);
        uint256 firstTime = c.pastBlockTime();

        // Second call: same block number won't work due to block.timestamp > pastBlockTime
        vm.warp(block.timestamp + 1);
        // Make a call that would transfer balance out if block.number % 15 == 0
        // We'll force a block where it's not multiple of 15 to avoid balance issues
        vm.roll(block.number + 1); // ensure block.number % 15 != 0 (probabilistic, but assume it's false)

        // Second call should succeed and update pastBlockTime
        (bool success2, ) = address(c).call{value: 10 ether}("");
        assertTrue(success2);

        // Now, if the bug were present, pastBlockTime could be 0 after a transfer
        // This call tests that pastBlockTime after transfer (if any) is not 0
        // But more directly: the property is that pastBlockTime never decreases
        assertTrue(c.pastBlockTime() >= firstTime);
    }
}

