pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed1, uint256 seed2) public {
        // Use seeds to create two different block timestamps
        uint256 t1 = bound(seed1, 1, 1000000);
        uint256 t2 = bound(seed2, t1 + 1, t1 + 1000000);

        // First call: send 10 ether at time t1
        vm.warp(t1);
        vm.deal(address(this), 10 ether);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        // Ensure first call succeeded
        vm.assume(ok1);

        // Second call at a later time t2: this should succeed
        vm.warp(t2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);
    }
}
